	,validateClient: function(cid) {
		var c = this.hotel.getClient(cid);
		var h = c.getHappiness();
		var ch = c.getCappedHappiness();
		var x = c.room.cx;
		var y = c.room.cy;
		this.applyEffect(com_GameEffect.ClientValidated(cid,h));
		if(c.type == com_ClientType.C_Bomb && h >= com_GameData.getHappinessTrigger(c.type,this.hotel)) {
			this.applyEffect(com_GameEffect.AddGift(c.room.cx,c.room.cy,com_Item.I_Money(1250)));
		}
		var v = c.skippedUsingGem() ? this.hotel.getMaxClientPayment(c.type) : this.hotel.getClientPayment(c);
		this.applyMoneyGain(null,c.room,v,c.skippedUsingGem() || ch >= this.hotel.getMaxHappiness() * 0.5);
		this.applyEffect(com_GameEffect.AddStat("cincome",v));
		if(c.type == com_ClientType.C_Halloween && (c.hasFlag("maxed") || c.getHappiness() >= c.hotel.getMaxHappiness())) {
			var rlist = new mt_RandList(($_=this.rseed,$bind($_,$_.random)));
			rlist.add(com_Item.I_Money(2000));
			this.applyEffect(com_GameEffect.AddGift(c.room.cx,c.room.cy,com_Item.I_EventGift(rlist.draw())));
		}
		if(c.type == com_ClientType.C_Christmas && (c.hasFlag("maxed") || c.getHappiness() >= c.hotel.getMaxHappiness())) {
			var rlist = new mt_RandList(($_=this.rseed,$bind($_,$_.random)));
			rlist.add(com_Item.I_Texture(35),8);
			rlist.add(com_Item.I_Bed(26),10);
			rlist.add(com_Item.I_Bath(15),7);
			rlist.add(com_Item.I_Ceil(13),10);
			rlist.add(com_Item.I_Furn(27),8);
			rlist.add(com_Item.I_Wall(23),10);
			this.applyEffect(com_GameEffect.AddGift(c.room.cx,c.room.cy,com_Item.I_EventGift(rlist.draw())));
		}
		if(c.hasPerk("Vip") && (c.hasFlag("maxed") || c.getHappiness() >= c.hotel.getMaxHappiness())) {
			if(this.hotel.featureUnlocked("custom")) {
				this.applyEffect(com_GameEffect.AddGift(x,y,com_Item.I_LunchBoxAll));
				if(c.hasPerk("DecoDropper")) {
					this.applyEffect(com_GameEffect.AddGift(x,y,com_Item.I_LunchBoxAll));
				}
			}
			var m = com_GameData.VIP_MONEY;
			if(c.hasPerk("DoubleReward")) {
				m *= 2;
			}
			this.applyEffect(com_GameEffect.AddGift(x,y,com_Item.I_Money(m)));
		}
		if(c.type == com_ClientType.C_Inspector && (c.hasFlag("maxed") || c.getHappiness() >= c.hotel.getMaxHappiness())) {
			if(this.hotel.featureUnlocked("custom")) {
				this.applyEffect(com_GameEffect.AddGift(x,y,com_Item.I_LunchBoxCusto));
			}
			this.applyEffect(com_GameEffect.AddGift(c.room.cx,c.room.cy,com_Item.I_Gem));
			this.applyEffect(com_GameEffect.AddGift(c.room.cx,c.room.cy,com_Item.I_Gem));
		}
		if(h <= 0) {
			this.hotel.addGoal("furious");
		}
		if(c.type == com_ClientType.C_Inspector && !(c.hasFlag("maxed") || c.getHappiness() >= c.hotel.getMaxHappiness())) {
			this.applyEffect(com_GameEffect.BossResult(false));
			this.applyEffect(com_GameEffect.BossCooldownReset(false));
		}
		if(c.type != com_ClientType.C_Inspector) {
			this.applyBossCdDec();
		}
		this.applyEffect(com_GameEffect.ClientLeft(cid));
		this.applyEffect(com_GameEffect.CheckMiniGame);
		if(this.hotel.inspectorReady() && !this.hotel.hasClient(com_ClientType.C_Inspector)) {
			var i = DataTools.getBoss(this.hotel.level);
			if(Boss.get_perk(i) == null || Boss.get_perk(i).id != "IMPOSSIBLE") {
				this.applyEffect(com_GameEffect.ClientArrived(com_ClientType.C_Inspector));
				this.applyEffect(com_GameEffect.BossArrived);
			}
		}
	}
